#!/usr/bin/env python3
"""チャートの下に出す「銘柄ごとのニュース一覧」のデータを作る。

Yahoo Finance の銘柄別ニュース配信(RSS、feeds.finance.yahoo.com)から、各銘柄の新しい見出しを最大 PER 件取る。
対象は検索一覧(search_index.json)の全銘柄と、ダッシュボード用の ohlc にある指数・ETF。
さらに、ダッシュボードに載る銘柄(ウォッチリスト・階層ビューの個別銘柄・指数・セクター・コモディティ)と、
売買代金(直近20日平均)の上位 JA_TOP 銘柄だけは、
Googleニュース日本語版(RSS、news.google.com)から日本語の記事も最大 PER 件取る(直近 JA_DAYS 日)。
それ以外の銘柄は、ページのリンクからGoogleニュースで探す。表示用で、判定には使わない。

出力(out/search/ 以下):
  news_<k>.json  k = ティッカーの文字コードの合計を CHUNKS で割った余り(月足と同じ分け方。ページ側も同じ計算で探す)
                 {"asof": 取得時刻, "rows": [{"t": ティッカー, "n": [[見出し, URL, UNIX秒, 配信元], ...], "j": 日本語記事(同じ形、ないときは省く)}]}

使い方:
  python make_news_data.py --out output [--threads 8] [--only-ja]   (--only-ja は既存の news_<k>.json に日本語記事だけ足し直す)
"""
from __future__ import annotations

import argparse
import re
import datetime as dt
import email.utils
import json
import time
import urllib.parse
import urllib.request
import xml.etree.ElementTree as ET
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

CHUNKS = 10
PER = 12
URL = "https://feeds.finance.yahoo.com/rss/2.0/headline?s={}&region=US&lang=en-US"
JA_DAYS = 30
JA_TOP = 600
JA_URL = "https://news.google.com/rss/search?q={}&hl=ja&gl=JP&ceid=JP:ja"
SUFFIX = re.compile(r"[,.]?\s+(Inc|Incorporated|Corporation|Corp|Company|Co|Ltd|Limited|plc|PLC|N\.V|S\.A|AG|SE|Holdings?|Group|Class [A-C].*|Common Stock.*|Ordinary Shares.*|American Depositary.*)\.?$")
UA = {"User-Agent": "Mozilla/5.0 (compatible; stage-checker)"}


def chunk_of(t: str) -> str:
    return str(sum(ord(ch) for ch in t) % CHUNKS)


def fetch(t: str):
    for a in range(3):
        try:
            req = urllib.request.Request(URL.format(urllib.parse.quote(t)), headers=UA)
            with urllib.request.urlopen(req, timeout=20) as r:
                root = ET.fromstring(r.read())
            out = []
            for it in root.iter("item"):
                title = (it.findtext("title") or "").strip()
                link = (it.findtext("link") or "").strip()
                if not title or not link.startswith("http"):
                    continue
                link = link.replace("?.tsrc=rss", "")
                try:
                    ts = int(email.utils.parsedate_to_datetime(it.findtext("pubDate") or "").timestamp())
                except Exception:
                    ts = None
                src = urllib.parse.urlparse(link).netloc.removeprefix("www.")
                out.append([title, link, ts, src])
            out.sort(key=lambda x: -(x[2] or 0))
            return t, out[:PER]
        except Exception:
            time.sleep(2 * (a + 1))
    return t, None


def short_name(n: str) -> str:
    n = (n or "").strip()
    for _ in range(3):
        n2 = SUFFIX.sub("", n).strip(" ,.")
        if n2 == n:
            break
        n = n2
    return n


def fetch_ja(arg):
    t, q = arg
    for a in range(3):
        try:
            req = urllib.request.Request(JA_URL.format(urllib.parse.quote(f"{q} when:{JA_DAYS}d")), headers=UA)
            with urllib.request.urlopen(req, timeout=20) as r:
                root = ET.fromstring(r.read())
            out = []
            for it in root.iter("item"):
                title = (it.findtext("title") or "").strip()
                link = (it.findtext("link") or "").strip()
                src = (it.findtext("source") or "").strip()
                if src and title.endswith(" - " + src):
                    title = title[: -len(src) - 3]
                try:
                    ts = int(email.utils.parsedate_to_datetime(it.findtext("pubDate") or "").timestamp())
                except Exception:
                    ts = None
                if title and link.startswith("http"):
                    out.append([title, link, ts, src])
            out.sort(key=lambda x: -(x[2] or 0))
            return t, out[:PER]
        except Exception:
            time.sleep(3 * (a + 1))
    return t, None


def ja_targets(out: Path, idx: list) -> dict[str, str]:
    """日本語ニュースを取る銘柄と検索語。ダッシュボードに載るものだけ。"""
    nm = {r["t"]: r.get("n") or r["t"] for r in idx}
    d = json.loads((out / "dashboard_data.json").read_text(encoding="utf-8"))
    q: dict[str, str] = {}
    for r in d.get("indices", []):
        q[r["ticker"]] = f'"{r["name"]}"'
    for r in d.get("sectors", []):
        q[r["etf"]] = f'米国株 "{r["sector"]}株"'
    for r in d.get("commodities", []):
        n = re.sub(r"[(（].*", "", r["name"]).strip()
        q[r["etf"]] = f'"{n}価格" OR "{n}相場"'
    # 売買代金の上位(よく取引される大型株など)
    dv = []
    for k in range(10):
        p = out / "search" / f"search_px_{k}.json"
        if not p.exists():
            continue
        for r in json.loads(p.read_text(encoding="utf-8"))["rows"]:
            c, v = r["c"][-20:], r["v"][-20:]
            x = [a * b * 100 for a, b in zip(c, v) if a is not None and b is not None]
            if x:
                dv.append((sum(x) / len(x), r["t"]))
    top = [t for _, t in sorted(dv, reverse=True)[:JA_TOP]]
    for t in [r["ticker"] for r in d.get("watchlist", [])] + [r["ticker"] for r in d.get("stocks", [])] + top:
        n = short_name(nm.get(t, t))
        if n and n != t:
            q[t] = f'"{n}" 株'
        elif len(t) >= 3:
            q[t] = f'{t} 株'
    return q


def add_ja(so: Path, targets: dict[str, str], threads: int) -> int:
    got: dict[str, list] = {}
    with ThreadPoolExecutor(threads) as ex:
        for t, items in ex.map(fetch_ja, targets.items()):
            if items:
                got[t] = items
    for k in range(CHUNKS):
        p = so / f"news_{k}.json"
        if not p.exists():
            continue
        body = json.loads(p.read_text(encoding="utf-8"))
        rows = {r["t"]: r for r in body["rows"]}
        for t, items in got.items():
            if chunk_of(t) == str(k):
                rows.setdefault(t, {"t": t, "n": []})["j"] = items
        body["rows"] = list(rows.values())
        body["meta"][0]["value"] = Path(__file__).read_text(encoding="utf-8")
        p.write_text(json.dumps(body, ensure_ascii=False, separators=(",", ":")), encoding="utf-8")
    return len(got)


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", default="output")
    ap.add_argument("--threads", type=int, default=8)
    ap.add_argument("--only-ja", action="store_true")
    args = ap.parse_args()
    so = Path(args.out) / "search"
    idx = json.loads((so / "search_index.json").read_text(encoding="utf-8"))["rows"]
    if args.only_ja:
        tg = ja_targets(Path(args.out), idx)
        print(f"日本語ニュース {add_ja(so, tg, 3)}/{len(tg)} 銘柄")
        return
    ohlc_path = Path(args.out) / "dashboard_ohlc.json"
    extra = [r["t"] for r in json.loads(ohlc_path.read_text())["rows"]] if ohlc_path.exists() else []
    tickers = list(dict.fromkeys(extra + [r["t"] for r in idx]))

    groups: dict[str, list] = {str(k): [] for k in range(CHUNKS)}
    ok = fail = 0
    with ThreadPoolExecutor(args.threads) as ex:
        for i, (t, items) in enumerate(ex.map(fetch, tickers), 1):
            if items is None:
                fail += 1
                continue
            ok += 1
            if items:
                groups[chunk_of(t)].append({"t": t, "n": items})
            if i % 500 == 0:
                print(f"{i}/{len(tickers)}", flush=True)
    asof = dt.datetime.now(dt.timezone.utc).isoformat(timespec="minutes")
    meta = [{"label": "make_news_data.py", "value": Path(__file__).read_text(encoding="utf-8"), "type": "code", "lang": "python"},
            {"label": "Input", "value": "Yahoo Finance 銘柄別ニュース配信(RSS)"}]
    for k, rows in groups.items():
        (so / f"news_{k}.json").write_text(json.dumps({"asof": asof, "rows": rows, "meta": meta}, ensure_ascii=False, separators=(",", ":")), encoding="utf-8")
    sizes = [(so / f"news_{k}.json").stat().st_size for k in groups]
    print(f"取得 {ok} 銘柄、失敗 {fail}、ニュースあり {sum(len(v) for v in groups.values())} 銘柄、最大 {max(sizes) / 1e6:.1f}MB")
    if ok == 0:
        raise SystemExit("ニュースを1件も取れませんでした")
    tg = ja_targets(Path(args.out), idx)
    print(f"日本語ニュース {add_ja(so, tg, 3)}/{len(tg)} 銘柄")


if __name__ == "__main__":
    main()
